(35812, 'Templates', 'change value of \'content\' from \'<h1 \">\r\n	OFFER CONFIRM&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;<img src=\"https://dev.eetstravel.com/img/eets_logo_small.jpg\" \" /></h1>\r\n<h1>\r\n	&nbsp;##tour_name##</h1>\r\n<div class=\"d-flex justify-content-between\" \">\r\n	<div \">\r\n		<p class=\"date text-end\" \">\r\n			&nbsp;</p>\r\n	</div>\r\n</div>\r\n<table border=\"1\" class=\"mt-3\" \">\r\n	<tbody \">\r\n		<tr \">\r\n			<td class=\"td1\" \">\r\n				<h1>\r\n					<span \">##name##</span></h1>\r\n			</td>\r\n			<td class=\"td1\" \">\r\n				<span \">##time_from##</span></td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n<p class=\"mt-3\" \">\r\n	Please quote from the following</p>\r\n<h1>\r\n	&nbsp;</h1>\r\n<table class=\"mt-3\" \">\r\n	<tbody \">\r\n		<tr \">\r\n			<td class=\"keys\" \">\r\n				Supplier :</td>\r\n			<td class=\"values\" \">\r\n				<span \">&nbsp;##name##</span></td>\r\n		</tr>\r\n		<tr \">\r\n			<td class=\"keys\" \">\r\n				Check in :</td>\r\n			<td class=\"values\" \">\r\n				<span \">##time_from##</span></td>\r\n		</tr>\r\n		<tr \">\r\n			<td class=\"keys\" \">\r\n				Check out :</td>\r\n			<td class=\"values\" \">\r\n				<span \">##time_to##</span></td>\r\n		</tr>\r\n		<tr \">\r\n			<td class=\"keys\" \">\r\n				Arrival Time:</td>\r\n			<td class=\"values\" \">\r\n				<span \">&nbsp;##arrival##</span></td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n<p>\r\n	&nbsp;</p>\r\n<p>\r\n	<span \">##roominglist##</span></p>\r\n<h1>\r\n	<span \">Offer</span></h1>\r\n<table border=\"1\" cellpadding=\"1\" cellspacing=\"1\" \">\r\n	<tbody>\r\n		<tr>\r\n			<td>\r\n				Reference No</td>\r\n			<td>\r\n				##offer_refno##</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n				Status</td>\r\n			<td>\r\n				##offer_status##</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n				Option Date&nbsp;</td>\r\n			<td>\r\n				##offer_option_date##</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n				City Tax</td>\r\n			<td>\r\n			