\n	<span \">Offer</span></h1>\r\n<table border=\"1\" cellpadding=\"1\" cellspacing=\"1\" \">\r\n	<tbody>\r\n		<tr>\r\n			<td>\r\n				Reference No</td>\r\n			<td>\r\n				##offer_refno##</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n				Status</td>\r\n			<td>\r\n				##offer_status##</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n				Option Date&nbsp;</td>\r\n			<td>\r\n				##offer_option_date##</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n				City Tax</td>\r\n			<td>\r\n				##offer_city_tax##</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n				Porterage Per Person</td>\r\n			<td>\r\n				##offer_porterage_pp##</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n				Halfboard Supp Per person</td>\r\n			<td>\r\n				##offer_halfboard_pp##</td>\r\n		</tr>\r\n		<tr>\r\n			<td>\r\n				Max Per Group</td>\r\n			<td>\r\n				##offer_max_per_group##</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\' at Templates \'Tour deleted\' in \'Hotel\' service', 28, 'App\\Templates', 5, 'App\\User', '{\"action\":\"updated\",\"link\":\"https:\\/\\/dev.eetstravel.com\\/templates\\/28\"}', '2024-04-11 10:51:48', '2024-04-11 10:51:48'),
