(475, NULL, '<h1>\n	<span style=\"font-size:28px;\">Request for quotation for ##tour_name##</span></h1>\n<p>\n	&nbsp;</p>\n<p>\n	<span style=\"font-size:22px;\">Dear Hotel partner,</span></p>\n<p>\n	&nbsp;</p>\n<p>\n	<span style=\"font-size:22px;\">Would you be so kind and check availability and offer us following:</span></p>\n<p>\n	&nbsp;</p>\n<table>\n	<tbody>\n		<tr>\n			<td>\n				<h1 style=\"box-sizing: border-box; margin-top: 0px; margin-bottom: 0.5rem; font-weight: 500; line-height: 1.2; font-size: 60px; font-family: &quot;Source Sans Pro&quot;, sans-serif;\">\n					<span style=\"font-size:22px;\">Supplier :</span></h1>\n			</td>\n			<td>\n				<span style=\"font-size:22px;\">&nbsp;##name##</span></td>\n		</tr>\n		<tr>\n			<td>\n				<span style=\"font-size:22px;\">Check in :</span></td>\n			<td>\n				<span style=\"font-size:22px;\">##time_from##</span></td>\n		</tr>\n		<tr>\n			<td>\n				<span style=\"font-size:22px;\">Check out :</span></td>\n			<td>\n				<span style=\"font-size:22px;\">##time_to##</span></td>\n		</tr>\n		<tr>\n			<td>\n				<span style=\"font-size:22px;\">Rooms:</span></td>\n			<td>\n				<span style=\"font-size:22px;\">&nbsp;##roominglist##</span></td>\n		</tr>\n	</tbody>\n</table>\n<p>\n	&nbsp;</p>\n<p>\n	<span style=\"font-size:22px;\">&nbsp;You can reply with an offer to this email or by filling out our offer form by&nbsp;</span></p>\n<p>\n	<span style=\"font-size:24px;\"><a data-cke-saved-href=\"https://dev.eetstravel.com/templates/0##supplier_url##\" href=\"##supplier_url##\">Clicking here</a>&nbsp;&nbsp;</span></p>\n<p>\n	&nbsp;</p>\n<p>\n	<span style=\"font-size:22px;\">Thank you from the EETS Team!</span></p>', 9, NULL, NULL, NULL, NULL, NULL, '2025-12-17 21:46:00', NULL, NULL, NULL, NULL, NULL, NULL, '2025-12-17 20:20:14', '2025-12-17 20:20:14', NULL, 1, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 1, 1, NULL, NULL, 0),
